  const [storageMode,setStorageMode]=useState('guest'),[personal,setPersonal]=useState(storedPersonalSheet),[chatId,setChatId]=useState(uid),[historyOpen,setHistoryOpen]=useState(false),[jumpVisible,setJumpVisible]=useState(false);
