  useEffect(()=>{api('status').then(async s=>{setConfig(s.config??{});const own=storedPersonalSheet();if(own){setStorageMode('loading');try{const result=await personalRequest(own,'read');activatePersonal(own,result);}catch(error){setStorageMode('cloud_error');tell('โหลด Sheet ส่วนตัวไม่สำเร็จ: '+error.message,'error');}return;}if(!s.user)return;setStorageMode('loading');setData(loadUserDraft(s.user));setUser(s.user);setConnection(s.connection??null);if(s.connection?.status==='ready'){try{const result=await api('data');setData(result.data);setCloudVersion(result.version);setStorageMode('cloud');}catch{setStorageMode('cloud_error');tell('โหลดข้อมูลออนไลน์ไม่สำเร็จ ระบบหยุดการแก้ไขไว้เพื่อป้องกันข้อมูลทับกัน','error');}}else setStorageMode('local_user');}).catch(()=>{});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});const p=new URLSearchParams(location.search);if(p.get('connected'))tell('เชื่อมบัญชีสำเร็จแล้ว พร้อมเริ่มวันของคุณ');if(p.get('googleLinked'))tell('เชื่อม Google ของคุณแล้ว ข้อมูลจะเก็บใน Drive และ Sheets ของคุณเอง');if(p.get('error'))tell('เชื่อมต่อไม่สำเร็จ กรุณาลองอีกครั้ง','error');if(p.get('draft')){try{const draft=JSON.parse(p.get('draft'));if(typeof draft.title==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(draft.date)){setModal({type:'event',isNew:true,requiresLine:p.get('source')==='line',value:{id:uid(),title:draft.title.slice(0,200),date:draft.date,time:draft.time??'09:00',endTime:draft.time?`${String(Math.min(23,+draft.time.slice(0,2)+1)).padStart(2,'0')}:${draft.time.slice(3)}`:'10:00',category:draft.category??'work',status:'active',repeat:'none',reminders:[30],channels:['line'],note:''}});}}catch{}}},[]);
  useEffect(()=>{if(storageMode==='guest')localStorage.setItem('dayzi:guest',JSON.stringify(data));else if(storageMode==='local_user'&&user)localStorage.setItem(`dayzi:user:${user.sub}`,JSON.stringify(data));},[data,user,storageMode]);
  function activatePersonal(own,result){setPersonal(own);setUser({sub:result.ownerId,name:result.data.settings?.name??'คุณ',provider:'personal'});setConnection({status:'ready',spreadsheetUrl:own.sheetUrl,provider:'personal'});setData({...result.data,settings:{...seedData().settings,...result.data.settings}});setCloudVersion(result.revision);setStorageMode('personal');setMessages([WELCOME]);setChatId(uid());}
  async function persist(next){if(storageMode==='loading'||storageMode==='cloud_error'){tell('ยังโหลดข้อมูลออนไลน์ไม่สำเร็จ กรุณารีเฟรชก่อนแก้ไข','error');return false;}if(syncRef.current){tell('กำลังบันทึก กรุณารอสักครู่','info');return false;}if(storageMode==='personal'){syncRef.current=true;setSyncing(true);try{const r=await personalRequest(personal,'write',{data:next,expectedRevision:cloudVersion});setCloudVersion(r.revision);setData(next);return true;}catch(error){tell(error.message,'error');return false;}finally{syncRef.current=false;setSyncing(false);}}if(storageMode==='cloud'){syncRef.current=true;setSyncing(true);try{const r=await api('data',{method:'PUT',body:JSON.stringify({data:next,expectedVersion:cloudVersion})});setCloudVersion(r.version);setData(next);return true;}catch(e){tell(e.status===409?'ข้อมูลเปลี่ยนจากอีกอุปกรณ์ กรุณารีเฟรชก่อนแก้ไข':e.message,'error');return false;}finally{syncRef.current=false;setSyncing(false);}}setData(next);return true;}
  useEffect(()=>{const check=()=>{if((user&&connection?.status==='ready')||isQuiet(data.settings))return;const due=dueReminders(data.events,new Date(),data.delivered);const push=due.filter(x=>x.channel==='push');if(!push.length)return;const next={...data,delivered:{...data.delivered}};for(const r of push){if('Notification'in window&&Notification.permission==='granted'){navigator.serviceWorker.ready.then(sw=>sw.showNotification(`ใกล้ถึงเวลา: ${r.event.title}`,{body:`${r.event.time} น. · ${r.event.note??''}`,icon:'/icon.svg',tag:r.key}));next.delivered[r.key]=true;}}if(Object.keys(next.delivered).length!==Object.keys(data.delivered).length)setData(next);};check();const id=setInterval(check,30000);return()=>clearInterval(id);},[data,user,connection]);
  const eventsFor=(date)=>data.events.filter(e=>e.status!=='cancelled'&&occursOn(e,date)&&(filter==='all'||e.category===filter)&&(!search||e.title.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>a.time.localeCompare(b.time));
  const todayEvents=eventsFor(today),activeTasks=data.tasks.filter(t=>!t.done),[year,mon]=month.split('-').map(Number);
  const moveMonth=(n)=>{const d=new Date(Date.UTC(year,mon-1+n,1));setMonth(d.toISOString().slice(0,7));};
  const newEvent=(date=selected)=>setModal({type:'event',value:{id:uid(),title:'',date,time:'09:00',endTime:'10:00',category:'work',status:'active',repeat:'none',reminders:[30],channels:['push'],note:'',fileIds:[]},isNew:true});
  async function saveEvent(e){if(modal.requiresLine&&!(user?.provider==='line'&&storageMode==='cloud')){tell('กรุณายืนยันบัญชี LINE และโหลดข้อมูลให้สำเร็จก่อนบันทึกนัดจาก LINE','error');return;}if(!e.title.trim()){tell('ใส่ชื่อนัดหมายก่อนนะคะ','error');return;}if(!e.allDay&&e.time>=e.endTime){tell('เวลาสิ้นสุดต้องอยู่หลังเวลาเริ่ม','error');return;}const conflict=findConflicts(data.events,e);if(conflict.length&&!modal.confirmConflict){setModal({...modal,confirmConflict:true,conflict:conflict.map(x=>x.title).join(', ')});return;}const result=await persist({...data,events:[...data.events.filter(x=>x.id!==e.id),{...e,sample:false,updatedAt:new Date().toISOString()}]});if(result){setModal(null);tell('บันทึกนัดหมายแล้ว 🌼');}}
